  $q$```csharp
Ziak z = new Ziak();
z.Pridaj(1);
z.Pridaj(3);
int v = z.Najlepsia();

class Ziak
{
    private List<int> znamky = new List<int>();

    public void Pridaj(int z)
    {
        znamky.Add(z);
    }

    public int Najlepsia()
    {
        int m = znamky[0];
        for (int i = 1; i < znamky.Count; i++)
        {
            if (znamky[i] < m)
                m = znamky[i];
        }
        return m;
    }
}
